changeSet.sql:
CREATE MATERIALIZED VIEW mv_daily_recon_summary AS SELECT t.trade_date, c.region, t.asset_class,
COUNT(*) AS total_trades,
COUNT(*) FILTER ( WHERE t.status = 'MATCHED' ) AS matched_trades,
ROUND( COALESCE(SUM(t.quantity * t.price),0)::NUMERIC, 2 ) AS gross_notional,
ROUND( ( COUNT(*) FILTER (WHERE t.status='MATCHED') * 100.0 ) / NULLIF(COUNT(*),0), 2 ) AS match_rate_pct
FROM trades t JOIN counterparties c ON t.counterparty_id = c.id
JOIN instruments i ON t.instrument_id = i.id
WHERE t.deleted_at IS NULL
GROUP BY t.trade_date, c.region, t.asset_class
WITH NO DATA;
CREATE UNIQUE INDEX uq_mv_daily_recon_summary ON mv_daily_recon_summary ( trade_date, region, asset_class );
CREATE INDEX idx_mv_daily_recon_summary_trade_date ON mv_daily_recon_summary(trade_date);
CREATE INDEX idx_mv_daily_recon_summary_region ON mv_daily_recon_summary(region);
REFRESH MATERIALIZED VIEW CONCURRENTLY mv_daily_recon_summary;
